pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }
    function testFuzz_property(uint256 warpTime, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        warpTime = bound(warpTime, 1, 1000000);
        amount = bound(amount, 1, 100 ether);
        vm.warp(warpTime);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);
        // Rule: a valueless plain-ether deposit routes through Put(0), so the
        // account must stay locked until at least the current block timestamp;
        // exactly max(0, block.timestamp) == block.timestamp.
        assertTrue(c.Acc(actor).unlockTime() == block.timestamp);
    }
}

