pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public { log = new Log(); c = new C(address(log)); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        uint256 before = log.History_length();
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok && log.History_length() == before + 1
            && log.getHistorySender(log.History_length() - 1) == actor
            && log.getHistoryVal(log.History_length() - 1) == amount);
    }
}

// No external counterparty behavior is needed beyond a normal caller, so no helper is required.
