// which returns the struct members via named tuple access in the console; we instead expose them
// through minimal wrappers below by re-using the Log's own public getters.

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public { log = new Log(); c = new C(address(log)); }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address actor) public {
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        (
            Log.Message memory,
            uint256,
            uint256
        ) memory unused;
        unused;

        (address sender, , uint256 val, ) = log.LastMsg();
        assertTrue(sender == actor && val == amount, "Put must be logged in LastMsg");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime, uint256 time) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1000 ether);
        time = bound(time, 1, 2 * 10 ** 12);
        vm.warp(time);

        vm.deal(actor, amount);
        uint256 beforeLen = log.History(0) == log.History(0) ? _len() : _len();
        beforeLen = _len();

        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        uint256 afterLen = _len();
        bool recorded = (afterLen == beforeLen + 1);
        if (recorded) {
            (address snd, string memory data, uint256 val, uint256 tm) = log.History(afterLen - 1);
            recorded = (snd == actor) && (val == amount) && (tm == time) &&
                (keccak256(bytes(data)) == keccak256(bytes("Put")));
        }
        assertTrue(recorded, "Put must append a log entry recording actor, amount, time and 'Put'");
    }

    function _len() internal view returns (uint256) {
        uint256 i = 0;
        while (true) {
            try log.History(i) returns (address, string memory, uint256, uint256) {
                i++;
            } catch {
                return i;
            }
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function test(uint amount) public payable {
        require(amount >= 1 ether);
        require(address(this).balance >= amount);
        c.Put{value: amount}(0);
        c.Collect(amount);
        assert(c.Acc(address(this)).balance == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amt, address logAddr) public {
        require(amt >= 1 ether);
        require(address(this).balance >= amt);

        c.Put{value: amt}(0);
        c.Collect(amt);

        (bool ok, bytes memory data) = logAddr.staticcall(
            abi.encodeWithSignature("History(uint256)", uint256(1))
        );
        require(ok);
        (address snd, string memory dt, uint val, uint tm) = abi.decode(
            data, (address, string, uint, uint)
        );
        assert(val == amt);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amt) public {
        require(amt >= 1 ether);
        require(address(this).balance >= amt);

        c.Put{value: amt}(0);   // balance = amt, unlockTime = now
        c.Collect(amt);         // pays this contract; receive() reenters Put

        (,,uint val1,) = c.History(1);
        // P: messages are [Put(amt), Collect(amt)] -> index 1 value == amt
        // M: reentrant Put(0) succeeds during Collect, so index 1 value == 0
        assert(val1 == amt);
    }

    receive() external payable {
        // Reentrant call: succeeds only in the mutant M (lock removed).
        address(c).call{value: 0, gas: 200000}(abi.encodeWithSignature("Put(uint256)", 0));
    }
}
